function PRODUCT_BASIN_COUNT(systems):           # systems = list of (states, step, energy)
    total <- 1
    for (states, step, energy) in systems:
        fixed <- count of s in states with step(s) == s
        total <- total * fixed                   # basins = fixed points (Thm 5.7)
    return total
